//! Minimal forgiving in-tree HTML parser: elements and text only.
use crate::model::*;
pub fn parse(input:&str)->Document{let mut st=vec![Node{kind:NodeKind::Element("document".into()),children:vec![]}];let mut r=input;while let Some(a)=r.find('<'){let t=&r[..a];if !t.trim().is_empty(){st.last_mut().unwrap().children.push(Node{kind:NodeKind::Text(t.trim().into()),children:vec![]})}let Some(b)=r[a..].find('>')else{break};let tag=r[a+1..a+b].trim();if tag.starts_with('/') {if st.len()>1{let n=st.pop().unwrap();st.last_mut().unwrap().children.push(n)}}else if !tag.starts_with('!'){let n=tag.split_whitespace().next().unwrap_or("").to_ascii_lowercase();if !n.is_empty(){st.push(Node{kind:NodeKind::Element(n),children:vec![]})}}r=&r[a+b+1..]}if !r.trim().is_empty(){st.last_mut().unwrap().children.push(Node{kind:NodeKind::Text(r.trim().into()),children:vec![]})}while st.len()>1{let n=st.pop().unwrap();st.last_mut().unwrap().children.push(n)}Document{root:st.pop().unwrap()}}
